## `backend.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws      = { source = "hashicorp/aws", version = "~> 5.0" }
    sops     = { source = "carlpett/sops", version = "~> 0.2" }
  }

  backend "s3" {
    bucket         = "acme-terraform-state"
    key            = "global/s3.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

