## Module: `modules/bucket/`

### `modules/bucket/variables.tf`

```hcl
variable "name" {
  description = "Name prefix for the S3 bucket"
  type        = string
}

variable "environment" {
  description = "Deployment environment (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be 'dev' or 'prod'."
  }
}

variable "enable_cross_region_replication" {
  description = "Enable cross-region replication (prod only)"
  type        = bool
  default     = false
}

variable "replication_target_region" {
  description = "Target region for cross-region replication"
  type        = string
  default     = "us-west-2"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}
```

### `modules/bucket/main.tf`

```hcl
# --- Primary Bucket ---

resource "aws_s3_bucket" "primary" {
  bucket = "${var.name}-${var.environment}"

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}"
  })
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_to_all_objects = true
    sse_algorithm        = "aws:kms"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --- Replication (conditional, prod only) ---

resource "aws_iam_role" "replication" {
  count = var.enable_cross_region_replication ? 1 : 0

  name = "${var.name}-${var.environment}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action  = "sts:AssumeRole"
      Effect  = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_cross_region_replication ? 1 : 0

  name = "${var.name}-${var.environment}-s3-replication-policy"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.primary.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicationCommonBucketList"
        ]
        Resource = ["${aws_s3_bucket.primary.arn}/object/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetBucketVersioning",
          "s3:PutReplicationConfiguration"
        ]
        Resource = [aws_s3_bucket.primary.arn]
      }
    ]
  })
}

resource "aws_s3_bucket_replication" "primary" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  role = aws_iam_role.replication[0].arn

  rules {
    id     = "replicate-to-${var.replication_target_region}"
    status = "Enabled"

    destination {
      bucket        = "aws://arn:aws:s3:::${var.name}-${var.environment}-replica"
      storage_class = "STANDARD"
      account_id    = data.aws_caller_identity.current.account_id
    }

    filter {
      prefix = ""
    }
  }

  depends_on = [aws_s3_bucket_versioning.primary]
}

# --- Replica Bucket (target for CRR) ---

resource "aws_s3_bucket" "replica" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = "${var.name}-${var.environment}-replica"

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-replica"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_to_all_objects = true
    sse_algorithm        = "aws:kms"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --- Replication KMS key grant ---

resource "aws_kms_key" "replication" {
  count             = var.enable_cross_region_replication ? 1 : 0
  description       = "KMS key for replication bucket encryption"
  deletion_window_in_days = 7

  tags = var.tags
}

data "aws_caller_identity" "current" {}
```

### `modules/bucket/outputs.tf`

```hcl
output "bucket_name" {
  description = "Name of the primary S3 bucket"
  value       = aws_s3_bucket.primary.id
}

output "bucket_arn" {
  description = "ARN of the primary S3 bucket"
  value       = aws_s3_bucket.primary.arn
}

output "replica_bucket_name" {
  description = "Name of the replica bucket (empty if not enabled)"
  value       = var.enable_cross_region_replication ? aws_s3_bucket.replica[0].id : null
}
```

