## Module: `modules/rds/`

### `modules/rds/variables.tf`

```hcl
variable "name" {
  description = "Name for the RDS instance"
  type        = string
}

variable "environment" {
  description = "Deployment environment"
  type        = string
}

variable "instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username"
  type        = string
}

variable "db_password" {
  description = "Master password (sensitive, provided via SOPS or vault)"
  type        = string
  sensitive   = true
}

variable "multi_az" {
  description = "Enable multi-AZ deployment"
  type        = bool
  default     = false
}

variable "backup_retention_days" {
  description = "Automated backup retention in days"
  type        = number
  default     = 7
  validation {
    condition     = var.backup_retention_days >= 7
    error_message = "backup_retention_days must be at least 7."
  }
}

variable "engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "15.4"
}

variable "vpc_security_group_ids" {
  description = "VPC security group IDs to attach"
  type        = list(string)
}

variable "subnet_ids" {
  description = "Subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "allowed_security_group_ids" {
  description = "Security group IDs allowed to connect (ingress)"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags to apply"
  type        = map(string)
  default     = {}
}
```

### `modules/rds/main.tf`

```hcl
# --- Security Group ---

resource "aws_security_group" "rds" {
  name        = "${var.name}-${var.environment}-rds-sg"
  description = "Allow inbound PostgreSQL from application security groups"
  vpc_id      = var.subnet_ids[0] # Derive VPC; in practice pass vpc_id explicitly or use data source

  ingress {
    description     = "PostgreSQL from application SGs"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_group_ids
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-rds-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# --- DB Subnet Group ---

resource "aws_db_subnet_group" "this" {
  name       = "${var.name}-${var.environment}"
  subnet_ids = var.subnet_ids

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-subnet-group"
  })
}

# --- KMS Key for Encryption ---

resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS ${var.environment} encryption"
  deletion_window_in_days = 7
  enable_key_rotation    = true

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-rds-kms"
  })
}

# --- RDS Instance ---

resource "aws_db_instance" "this" {
  identifier     = "${var.name}-${var.environment}"
  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = var.instance_class
  allocated_storage = var.allocated_storage
  storage_type   = "gp3"
  storage_encrypted = true
  kms_key_id     = aws_kms_key.rds.arn

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password

  multi_az = var.multi_az

  backup_retention_period = var.backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"
  deletion_protection     = true
  publicly_accessible     = false

  vpc_security_group_ids = [aws_security_group.rds.id]
  db_subnet_group_name   = aws_db_subnet_group.this.name

  skip_final_snapshot = false
  final_snapshot_identifier = "${var.name}-${var.environment}-final-${formatdate("YYYYMMDDHHmmss", timestamp())}"

  performance_insights_enabled = true
  performance_insights_retention_period = var.environment == "prod" ? 90 : 7

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-rds"
  })
}
```

### `modules/rds/outputs.tf`

```hcl
output "endpoint" {
  description = "RDS endpoint (host:port)"
  value       = aws_db_instance.this.endpoint
}

output "address" {
  description = "RDS hostname"
  value       = aws_db_instance.this.address
}

output "port" {
  description = "RDS port"
  value       = aws_db_instance.this.port
}

output "security_group_id" {
  description = "Security group ID for the RDS instance"
  value       = aws_security_group.rds.id
}

output "connection_string" {
  description = "Full connection string (sensitive)"
  value       = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.this.endpoint}/${var.db_name}"
  sensitive   = true
}
```

