## Module: `modules/iam/`

### `modules/iam/variables.tf`

```hcl
variable "name" {
  description = "Base name for IAM resources"
  type        = string
}

variable "environment" {
  description = "Deployment environment"
  type        = string
}

variable "oidc_provider_arn" {
  description = "ARN of the OIDC identity provider (for prod IRSA)"
  type        = string
  default     = ""
}

variable "oidc_namespace" {
  description = "OIDC namespace for the service account"
  type        = string
  default     = "default"
}

variable "oidc_service_account" {
  description = "OIDC service account name"
  type        = string
  default     = "app-service"
}

variable "bucket_arn" {
  description = "ARN of the S3 bucket the service can access"
  type        = string
}

variable "tags" {
  description = "Tags to apply"
  type        = map(string)
  default     = {}
}
```

### `modules/iam/main.tf`

```hcl
# --- Service Role (for EC2/EKS node access) ---

resource "aws_iam_role" "service" {
  name = "${var.name}-${var.environment}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })

  tags = var.tags
}

# --- S3 Access Policy (scoped, no wildcards in prod) ---

resource "aws_iam_role_policy" "s3_access" {
  name = "${var.name}-${var.environment}-s3-access"
  role = aws_iam_role.service.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [var.bucket_arn]
      },
      {
        Sid    = "ObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts"
        ]
        Resource = ["${var.bucket_arn}/*"]
      }
    ]
  })
}

# --- KMS Policy for SSE-KMS objects ---

resource "aws_iam_role_policy" "kms_access" {
  name = "${var.name}-${var.environment}-kms-access"
  role = aws_iam_role.service.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["kms:Decrypt"]
      Resource = [data.aws_iam_policy_document.kms_allow.arn] # Simplified; in practice reference specific key ARN
    }]
  })
}

# --- OIDC Trust Policy for IRSA (prod) ---

resource "aws_iam_role" "irsa" {
  count = var.environment == "prod" ? 1 : 0

  name = "${var.name}-${var.environment}-irsa-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRoleWithWebIdentity"
      Effect = "Allow"
      Principal = {
        Federated = var.oidc_provider_arn
      }
      Condition = {
        StringEquals = {
          "${replace(var.oidc_provider_arn, "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/", "")}:sub" = "serviceaccount:${var.oidc_namespace}:${var.oidc_service_account}"
        }
      }
    }]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "irsa_s3" {
  count = var.environment == "prod" ? 1 : 0

  name = "${var.name}-${var.environment}-irsa-s3"
  role = aws_iam_role.irsa[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListBucket"
        Effect = "Allow"
        Action = ["s3:ListBucket"]
        Resource = [var.bucket_arn]
      },
      {
        Sid    = "GetObject"
        Effect = "Allow"
        Action = ["s3:GetObject"]
        Resource = ["${var.bucket_arn}/*"]
      }
    ]
  })
}

data "aws_caller_identity" "current" {}
```

### `modules/iam/outputs.tf`

```hcl
output "service_role_arn" {
  description = "ARN of the service IAM role"
  value       = aws_iam_role.service.arn
}

output "irsa_role_arn" {
  description = "ARN of the IRSA role (prod only, empty otherwise)"
  value       = var.environment == "prod" ? aws_iam_role.irsa[0].arn : null
}
```

