## Module: `modules/eks/`

### `modules/eks/variables.tf`

```hcl
variable "name" {
  description = "Cluster name"
  type        = string
}

variable "environment" {
  description = "Deployment environment"
  type        = string
}

variable "vpc_id" {
  description = "VPC ID"
  type        = string
}

variable "subnet_ids" {
  description = "Subnet IDs for the cluster"
  type        = list(string)
}

variable "node_instance_type" {
  description = "Instance type for managed node group"
  type        = string
}

variable "node_count" {
  description = "Desired number of nodes"
  type        = number
}

variable "node_min" {
  description = "Minimum nodes for scaling"
  type        = number
  default     = 1
}

variable "node_max" {
  description = "Maximum nodes for scaling"
  type        = number
  default     = 0
}

variable "iam_service_role_arn" {
  description = "IAM role ARN for the service (attached to node group)"
  type        = string
}

variable "tags" {
  description = "Tags"
  type        = map(string)
  default     = {}
}
```

### `modules/eks/main.tf`

```hcl
# --- IAM Roles ---

data "aws_iam_policy_document" "eksservice" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eksservice_policy" {
  statement {
    actions = ["ec2:Describe*vpcs", "ec2:DescribeSubnets", "ec2:DescribeSecurityGroups"]
    resources = ["*"]
  }

  statement {
    actions = ["ec2:DescribeRouteTables"]
    resources = ["*"]
  }
}

resource "aws_iam_role" "cluster" {
  name               = "${var.name}-${var.environment}-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.eksservice.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "node_group" {
  name = "${var.name}-${var.environment}-node-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "node_group_worker" {
  role       = aws_iam_role.node_group.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_group_cni" {
  role       = aws_iam_role.node_group.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# --- OIDC Provider ---

resource "aws_iam_openid_connect_provider" "oidc" {
  count = var.environment == "prod" ? 1 : 0

  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [] # AWS fetches automatically when URI is valid

  url = "https://oidc.eks.us-east-1.amazonaws.com/id/${var.name}-${var.environment}"

  tags = var.tags
}

# --- VPC / Subnets (assumed pre-existing; data sources) ---

# In a real project you'd have a VPC module. Here we accept vpc_id + subnet_ids.

# --- EKS Cluster ---

resource "aws_eks_cluster" "this" {
  name     = "${var.name}-${var.environment}"
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids              = var.subnet_ids
    endpoint_public_access  = false
    endpoint_private_access = true
    security_group_ids      = [aws_security_group.cluster.id]
  }

  enabled_cluster_log_types = ["api", "audit", "authenticator"]

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}"
  })

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
  ]
}

# --- Cluster Security Group ---

resource "aws_security_group" "cluster" {
  name        = "${var.name}-${var.environment}-cluster-sg"
  description = "EKS cluster security group"
  vpc_id      = var.vpc_id

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-cluster-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "cluster_ingress" {
  count             = var.environment == "prod" ? 1 : 0
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  security_group_id = aws_security_group.cluster.id
  cidr_blocks       = ["0.0.0.0/0"]
  description       = "Allow HTTPS to cluster API (for external access via NAT)"
}

# --- Node Group Security Group ---

resource "aws_security_group" "node_group" {
  name        = "${var.name}-${var.environment}-node-sg"
  description = "EKS node group security group"
  vpc_id      = var.vpc_id

  ingress {
    description = "Allow node-to-node communication"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-node-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# --- Managed Node Group ---

resource "aws_eks_node_group" "this" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "${var.name}-${var.environment}-mg"
  node_role_arn   = aws_iam_role.node_group.arn
  subnet_ids      = var.subnet_ids

  instance_types = [var.node_instance_type]
  scaling_config {
    desired_size = var.node_count
    min_size     = var.node_min
    max_size     = var.node_max > 0 ? var.node_max : var.node_count
  }

  capacity_type  = "ON_DEMAND"
  disk_size      = 50

  tags = merge(var.tags, {
    Name = "${var.name}-${var.environment}-node-group"
  })

  depends_on = [kubernetes_service_account.oidc]
}

